(new WOW).init(); var ABOUT = { init: function () { ABOUT.build.timeline() }, build: { timeline: function () { $("#example").horizontalTimeline({ dateDisplay: "year", desktopDateIntervals: 150, mobileDateIntervals: 100, scrollLeft_iconClass: "fa-arrow-circle-left", scrollRight_iconClass: "fa-arrow-circle-right", prev_iconClass: "fa-chevron-circle-left", next_iconClass: "fa-chevron-circle-right" }), $(".timeline-dots li button").click(function () { $(window).scroll() }) } } }; $(document).ready(ABOUT.init);


$(document).ready(function () {
    $(".toggle-tab-item").click(function () {
        if (!$(this).hasClass('active')) {

            var target = $(this).data('target');
            $(".about-2026").hide();
            $(target).fadeIn(1000);

            $(".toggle-tab-item").removeClass('active');
            $(this).addClass('active');
        }
    });
});